def page() -> str:
    return r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Telemetry Pit Crew</title>
<style>
:root{color-scheme:dark;--bg:#101014;--night:#101014;--panel:#19191f;--raised:#212129;--line:#35353e;--ink:#f5f5f7;--paper:#f5f5f7;--muted:#a9a9b5;--red:#f33b40;--acid:#ff686c;--lime:#b8f28b;--cyan:#64d8ff;--mono:ui-monospace,SFMono-Regular,Consolas,monospace;--display:"Arial Narrow","Helvetica Neue",Arial,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}body:before{content:"";display:block;height:5px;background:var(--red)}a{color:inherit}button,select,input{font:inherit}button,a,select,summary{-webkit-tap-highlight-color:transparent}a:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid #fff;outline-offset:5px}button{cursor:pointer}button:disabled{opacity:.55;cursor:wait}h1,h2,h3,p{overflow-wrap:break-word}h1,h2,h3{font-family:var(--display)}.lab-nav{width:min(1240px,calc(100% - 64px));margin:auto;display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:78px;border-bottom:1px solid var(--line);font:11px var(--mono);text-transform:uppercase;letter-spacing:.06em}.lab-nav>a:first-child{font:850 14px var(--display);letter-spacing:-.02em;color:var(--ink)}.lab-nav>a:first-child:before{content:"";display:inline-block;width:25px;height:14px;background:repeating-linear-gradient(0deg,transparent 0 3px,var(--red) 3px 6px);transform:skewX(-30deg);margin-right:12px}.lab-nav a{text-decoration:none;display:inline-flex;align-items:center;min-height:48px;color:var(--muted)}.lab-nav span{display:flex;gap:20px;flex-wrap:wrap}.lab-nav a:hover{color:#fff}.lab-nav [aria-current="page"]{color:#fff;box-shadow:inset 0 -3px var(--red)}.eyebrow,.kicker{font:11px/1.5 var(--mono);letter-spacing:.15em;text-transform:uppercase;color:#ff777b}.eyebrow:before,.kicker:before{content:"";display:inline-block;width:22px;height:3px;background:var(--red);vertical-align:middle;margin-right:10px}.lab-footer{max-width:1240px;margin:32px auto 0;padding:25px 0;border-top:1px solid var(--line);font:11px/1.7 var(--mono);color:var(--muted)}@media(max-width:760px){.lab-nav{width:calc(100% - 32px);gap:12px;flex-wrap:wrap;padding:12px 0}.lab-nav span{gap:18px}.lab-nav a{min-height:40px}.lab-nav>a:first-child{font-size:12px}.lab-footer{margin:28px 16px 0}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{transition:none!important;animation:none!important}}

header{width:min(1240px,calc(100% - 64px));margin:auto;padding:32px 0 24px;position:relative;border-bottom:1px solid var(--line)}header:after{content:"02";position:absolute;right:12px;top:70px;font:italic 950 130px/1 var(--display);color:#ffffff08;pointer-events:none}header nav{display:flex;justify-content:space-between;align-items:center;gap:20px}.brand{font:800 12px var(--mono);letter-spacing:.04em}.brand i{font-style:normal;color:#ff8287}.status{font:9px var(--mono);letter-spacing:.1em;color:#c2c2cb;border:1px solid #474752;border-radius:2px;padding:7px 10px;background:#202027}.status:before{content:"";display:inline-block;width:5px;height:5px;background:#b8f28b;margin-right:7px;border-radius:50%}.eyebrow{margin:24px 0 12px}.hero{font-weight:950;font-style:italic;letter-spacing:-.055em;text-transform:uppercase;line-height:1.03;font-size:clamp(36px,5vw,62px);margin:0;max-width:900px}.sub{font-size:13px;line-height:1.8;max-width:700px;color:var(--muted);margin:16px 0 0}main{width:min(1240px,calc(100% - 64px));margin:25px auto 45px}.control{display:grid;grid-template-columns:1.3fr 1fr 1fr auto;gap:14px;align-items:end;background:var(--panel);border:1px solid var(--line);border-top:3px solid var(--red);border-radius:3px 16px 3px 3px;padding:21px}.field{min-width:0}.field label{display:block;font:10px var(--mono);text-transform:uppercase;letter-spacing:.08em;color:#b9b9c4;margin:0 0 9px}.field select,.field input{width:100%;color:#f5f5f7;background:#111116;border:1px solid #454550;border-radius:3px;padding:12px 10px;font-size:12px;min-height:44px}.field select:focus,.field input:focus{outline:1px solid #ff777b}button{background:#d91f2a;border:1px solid #d91f2a;border-radius:3px;color:#fff;padding:12px 20px;font-size:12px;font-weight:750;min-height:44px;white-space:nowrap;transition:background .2s}button:hover{background:var(--red)}.source{display:flex;gap:10px;align-items:start;font-size:11px;line-height:1.65;color:var(--muted);margin:16px 0 24px;padding:0 3px}.source b{color:#ececf0;font-size:12px}.dot{width:5px;height:5px;border-radius:50%;background:#b8f28b;flex:none;margin-top:7px}.hidden{display:none!important}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.metric{background:#1c1c23;border:1px solid var(--line);border-radius:3px 14px 3px 3px;padding:20px 24px;position:relative}.metric:first-child{border-left:4px solid var(--red)}.metric:last-child{border-left:4px solid var(--cyan)}.metric:nth-child(2){border-left:4px solid #b8f28b}.metric .label{font:10px var(--mono);text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.metric .value{font:850 italic 38px var(--display);letter-spacing:-.04em;line-height:1.3;margin-top:6px}.metric:nth-child(2) .value{font-family:var(--mono);font-size:32px;font-style:normal;letter-spacing:-.06em;color:#b8f28b}.grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,.8fr);gap:18px;margin-top:20px;align-items:start}.card{padding:23px;background:var(--panel);border:1px solid var(--line);border-radius:3px 16px 3px 3px}.card h2{font:700 11px var(--mono);text-transform:uppercase;letter-spacing:.08em;margin:0 0 22px;display:flex;align-items:center;gap:9px}.card h2:before{content:"";display:inline-block;width:5px;height:12px;background:var(--red)}.chart{height:245px;width:100%;background:#131318;padding:8px;border-radius:2px}.chart.small{height:170px}.chart svg{width:100%;height:100%;overflow:visible}.axis{stroke:#4d4d59;stroke-width:1}.gridline{stroke:#30303a;stroke-width:1}.chart-label{fill:#aaaaba;font:10px var(--mono)}.legend{display:flex;gap:20px;color:#c4c4cf;font:10px var(--mono);margin-top:16px}.key:before{content:"";display:inline-block;width:16px;height:3px;background:var(--c);vertical-align:middle;margin-right:8px}.findings{display:grid;gap:13px;counter-reset:findings}.finding{padding:16px;background:#22222a;border-top:2px solid #555560;border-radius:2px}.finding b{display:block;font:700 10px var(--mono);letter-spacing:.06em;text-transform:uppercase;color:#ff969a;margin-bottom:10px}.finding b:before{counter-increment:findings;content:"0" counter(findings) " / ";color:#c7c7d1}.finding p{margin:0;font-size:13px;line-height:1.7}.finding small{display:block;font-size:11px;color:var(--muted);margin-top:10px;line-height:1.6}.notice{margin-top:18px;padding:16px 20px;border-left:3px solid #626270;background:#1c1c23;color:#b9b9c5;font-size:11px;line-height:1.7}.empty{padding:40px 20px;color:var(--muted);text-align:center;font-size:13px}details{margin-top:28px;border-top:1px solid var(--line);padding-top:8px}summary{cursor:pointer;color:#dddde5;font-size:12px;padding:14px 0;min-height:44px}.load-grid{display:grid;grid-template-columns:.7fr 1.6fr .7fr 1fr auto;gap:12px;align-items:end;margin-top:16px}.load-grid button{background:#34343e;border-color:#555560}.error{color:#ff939a;font-size:12px;margin-top:12px}footer{width:min(1240px,calc(100% - 64px));margin:auto;padding:24px 0;border-top:1px solid var(--line);color:var(--muted);font:10px/1.8 var(--mono)}@media(max-width:900px){.control{grid-template-columns:1.2fr 1fr 1fr}.control button{grid-column:1/-1}.grid{grid-template-columns:1fr}}@media(max-width:760px){header,main,footer{width:calc(100% - 32px)}header{padding-top:24px}header:after{font-size:80px}.hero{font-size:40px}.sub{font-size:12px}.control{grid-template-columns:1fr 1fr;padding:17px;gap:12px}.control .field:first-child{grid-column:1/-1}.metrics{gap:8px}.metric{padding:14px 10px;border-radius:2px 10px 2px 2px}.metric .value{font-size:28px}.metric:nth-child(2) .value{font-size:18px;line-height:2}.metric .label{font-size:8px;letter-spacing:0}.card{padding:18px}.chart{height:210px}.load-grid{grid-template-columns:1fr 1fr}.load-grid .field:nth-child(2),.load-grid button{grid-column:1/-1}.status{font-size:8px}.brand{font-size:10px}}
</style></head>
<body><nav class="lab-nav" aria-label="Lab navigation"><a href="/">↖ F1 ECOSYSTEM</a><span><a href="/pitwall/">Replay</a><a href="/scoutgrid/">ScoutGrid</a><a href="/claimcheck/">ClaimCheck</a><a href="/stewardlens/">StewardLens ↗</a><a href="/telemetry/" aria-current="page">Telemetry</a></span></nav>
<header><nav><div class="brand">TELEMETRY <i>PIT CREW</i></div><div class="status">RECORDED SESSIONS</div></nav><p class="eyebrow">02 / PERFORMANCE WORKSTATION</p><h1 class="hero">FIND THE <span style="color:var(--red)">MISSING TENTH.</span></h1><p class="sub">Compare recorded Formula 1 laps. Four specialist agents examine braking, cornering, traction and straight-line performance, then return one evidence-linked debrief.</p></header>
<main>
  <section class="control" aria-label="Comparison controls">
    <div class="field"><label for="session">Session</label><select id="session"></select></div>
    <div class="field"><label for="lapA">Driver A</label><select id="lapA"></select></div>
    <div class="field"><label for="lapB">Driver B</label><select id="lapB"></select></div>
    <button id="run" onclick="compare()">Analyse laps →</button>
  </section>
  <div class="source"><span class="dot"></span><div><b id="sourceTitle">Loading sessions…</b><br><span id="sourceNote"></span></div></div>
  <section id="output" class="hidden">
    <div class="metrics"><div class="metric"><div class="label">Driver A</div><div class="value" id="driverA">—</div></div><div class="metric"><div class="label">Lap delta · A − B</div><div class="value delta" id="delta">—</div></div><div class="metric"><div class="label">Driver B</div><div class="value" id="driverB">—</div></div></div>
    <div class="grid"><div>
      <div class="card"><h2>Speed trace · km/h</h2><div id="speedChart" class="chart"></div><div class="legend"><span class="key" style="--c:var(--red)">Driver A</span><span class="key" style="--c:var(--cyan)">Driver B</span></div></div>
      <div class="card" style="margin-top:16px"><h2>Throttle trace · %</h2><div id="throttleChart" class="chart small"></div><div class="legend"><span class="key" style="--c:var(--red)">Driver A</span><span class="key" style="--c:var(--cyan)">Driver B</span></div></div>
    </div><aside class="card"><h2>Race engineer priorities</h2><div id="findings" class="findings"></div></aside></div>
    <div id="limitations" class="notice"></div>
  </section>
  <div id="empty" class="empty">Select a session and run the engineering debrief.</div>
  <details><summary>Load another session with FastF1 (optional; requires network and the f1 dependency)</summary><div class="load-grid"><div class="field"><label>Year</label><input id="year" value="2024" inputmode="numeric"></div><div class="field"><label>Event</label><input id="event" value="Monza"></div><div class="field"><label>Session</label><select id="sessionCode"><option>Q</option><option>R</option><option>FP1</option><option>FP2</option><option>FP3</option><option>S</option></select></div><div class="field"><label>Drivers</label><input id="drivers" value="NOR,PIA"></div><button id="load" onclick="loadFastF1()">Load session</button></div><div id="loadError" class="error"></div></details>
</main><footer>Educational, unofficial project. Not affiliated with Formula 1, FIA, teams or drivers. Verify analytical conclusions against authoritative sources.</footer>
<script>
let sessions=[];
const $=id=>document.getElementById(id);
const esc=value=>String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function json(url,options){const response=await fetch(url,options);const body=await response.json();if(!response.ok)throw new Error(body.detail||'Request failed');return body}
async function init(preferred){sessions=await json('/sessions');$('session').innerHTML=sessions.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');$('session').value=(sessions.some(s=>s.id===preferred)?preferred:null)||sessions.find(s=>s.source_type!=='synthetic')?.id||sessions[0].id;await changeSession()}
async function changeSession(){const id=$('session').value,session=sessions.find(s=>s.id===id);const laps=await json(`/laps?session_id=${encodeURIComponent(id)}`);const options=laps.map(l=>`<option value="${esc(l.id)}">${esc(l.driver)} · ${Number(l.lap_time).toFixed(3)}s · lap ${l.lap_number}</option>`).join('');$('lapA').innerHTML=options;$('lapB').innerHTML=options;if(laps[1])$('lapB').value=laps[1].id;$('sourceTitle').textContent=session.source_type==='synthetic'?'Synthetic fallback':session.name;$('sourceNote').textContent=session.notes||''}
$('session').addEventListener('change',changeSession);
function lineChart(node,a,b,key,minOverride,maxOverride){const W=800,H=240,p={l:38,r:10,t:10,b:25};const all=[...a.samples,...b.samples];const maxX=Math.max(...all.map(x=>x.distance)),values=all.map(x=>Number(x[key]));const minY=minOverride??Math.min(...values),maxY=maxOverride??Math.max(...values);const x=v=>p.l+(v/maxX)*(W-p.l-p.r),y=v=>p.t+(maxY-v)/(maxY-minY||1)*(H-p.t-p.b);const points=lap=>lap.samples.map(s=>`${x(s.distance).toFixed(1)},${y(Number(s[key])).toFixed(1)}`).join(' ');let grid='';for(let i=0;i<5;i++){const gy=p.t+i*(H-p.t-p.b)/4;const label=Math.round(maxY-i*(maxY-minY)/4);grid+=`<line class="gridline" x1="${p.l}" y1="${gy}" x2="${W-p.r}" y2="${gy}"/><text class="chart-label" x="2" y="${gy+3}">${label}</text>`}node.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${esc(key)} comparison chart">${grid}<line class="axis" x1="${p.l}" y1="${H-p.b}" x2="${W-p.r}" y2="${H-p.b}"/><polyline fill="none" stroke="#f33b40" stroke-width="2.5" vector-effect="non-scaling-stroke" points="${points(a)}"/><polyline fill="none" stroke="#64d8ff" stroke-width="2.5" vector-effect="non-scaling-stroke" points="${points(b)}"/><text class="chart-label" x="${W-80}" y="${H-5}">distance →</text></svg>`}
async function compare(){const button=$('run');button.disabled=true;button.textContent='Analysing…';$('empty').textContent='Agents are reviewing the telemetry…';try{const ids=[$('lapA').value,$('lapB').value];const [result,a,b]=await Promise.all([json('/comparisons',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({lap_a_id:ids[0],lap_b_id:ids[1]})}),json(`/laps/${encodeURIComponent(ids[0])}/telemetry`),json(`/laps/${encodeURIComponent(ids[1])}/telemetry`)]);$('driverA').textContent=a.driver;$('driverB').textContent=b.driver;const d=Number(result.total_delta_seconds);$('delta').textContent=`${d>0?'+':''}${d.toFixed(3)} s`;$('findings').innerHTML=result.priority_findings.map(f=>`<article class="finding"><b>${esc(f.agent)} agent · ${esc(f.segment_id)}</b><p>${esc(f.finding)}</p><small>${esc(f.limitation)} · Confidence ${Math.round(f.confidence*100)}%</small></article>`).join('');$('limitations').textContent=result.data_limitations.join(' ');lineChart($('speedChart'),a,b,'speed');lineChart($('throttleChart'),a,b,'throttle',0,100);$('output').classList.remove('hidden');$('empty').classList.add('hidden')}catch(error){$('empty').classList.remove('hidden');$('empty').textContent=error.message}finally{button.disabled=false;button.textContent='Analyse laps →'}}
async function loadFastF1(){const button=$('load');button.disabled=true;$('loadError').textContent='Loading can take a few minutes on first use…';try{const result=await json('/sessions/fastf1',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({year:Number($('year').value),event:$('event').value,session_code:$('sessionCode').value,drivers:$('drivers').value.split(',').map(x=>x.trim()).filter(Boolean)})});$('loadError').textContent='Session loaded.';await init(result.id)}catch(error){$('loadError').textContent=error.message}finally{button.disabled=false}}
init(new URLSearchParams(location.search).get('session')).then(compare).catch(error=>{$('empty').textContent=error.message});
</script></body></html>"""
